pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner at deploy is address(0)
        // Attempt to transfer ownership from address(1) - non-owner
        address nonOwner = address(1);
        vm.prank(nonOwner);
        bool ok;
        try c.transferOwnership(address(2)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference: onlyOwner requires msg.sender == owner (address(0)), but nonOwner is address(1), so reverts, ok == false
        // In buggy: onlyOwner requires msg.sender != owner, which is true for nonOwner, so succeeds, ok == true
        // Assert that the call reverts (reference behavior)
        assertTrue(!ok);
    }
}

