// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up actors: Alice (non-owner) and Bob (initial owner)
        address alice = address(0x1234);
        address bob = address(0x5678);

        // Transfer ownership from default owner (deployer) to Bob in setUp is not possible directly.
        // Instead, we prank the deployer (this contract) to transfer ownership to Bob
        c.transferOwnership(bob);

        // Now Bob is owner. Alice calls owned() – should not revert; we just call it.
        vm.prank(alice);
        c.owned();

        // Now Bob calls transferOwnership with alice as newOwner
        vm.prank(bob);
        c.transferOwnership(alice);

        // After reference: owner = alice; after bug: owner = bob (unchanged).
        // Verify that alice (now supposed new owner) can call owned() without revert
        vm.prank(alice);
        // Try call; catch if revert
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

